use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclimpl! {
impl DummyResult { # [doc = " Creates a default MacResult that can be anything."] # [doc = ""] # [doc = " Use this as a return value after hitting any errors and"] # [doc = " calling `span_err`."] pub fn any < DRT : OpaqueDeriveResolution + 'static > (span : Span , guar : ErrorGuaranteed) -> Box < dyn MacResult < DRT > + 'static > { Box :: new (DummyResult { guar : Some (guar) , span }) } # [doc = " Same as `any`, but must be a valid fragment, not error."] pub fn any_valid < DRT : OpaqueDeriveResolution + 'static > (span : Span) -> Box < dyn MacResult < DRT > + 'static > { Box :: new (DummyResult { guar : None , span }) } # [doc = " A plain dummy expression."] pub fn raw_expr (sp : Span , guar : Option < ErrorGuaranteed >) -> Box < ast :: Expr > { Box :: new (ast :: Expr { id : ast :: DUMMY_NODE_ID , kind : if let Some (guar) = guar { ExprKind :: Err (guar) } else { ExprKind :: Tup (ThinVec :: new ()) } , span : sp , attrs : ast :: AttrVec :: new () , tokens : None , }) } }
}